import json
from taf.internal.aliasing import AliasStore
from taf.internal.sbts.admin.cli.util import ensure_parent_dir_exists


class DeltaParameter(dict):

    def __init__(self, name, value, operation="update"):
        super(DeltaParameter, self).__init__(parameterName=name, value=value, operation=operation)

    def __getattr__(self, attr):
        return self.get(attr)

    def __setattr__(self, attr, value):
        self[attr] = value


class DeltaManagedObject(object):

    def __init__(self, dist_name, operation="update"):
        self.dist_name = dist_name
        self.operation = operation
        self.parameters = {}

    def serialize(self):
        """Get serialized managed object JSON."""
        return {"distName": self.dist_name, "operation": self.operation, "parameters": list(self.parameters.values())}

    def append_parameter(self, parameter_name, value, operation="update"):
        """Add parameter to managed object."""
        self.parameters[parameter_name] = DeltaParameter(parameter_name, value, operation)

    def append_list_items(self, list_name, *args):
        """Add list item to managed object."""
        self._get_list(list_name).extend(args)

    def append_complex_item(self, list_name, **kwargs):
        """Add coplex type item to managed object."""
        self._get_list(list_name).append(kwargs)

    def _get_list(self, list_name):
        if list_name not in self.parameters:
            self.parameters[list_name] = DeltaParameter(list_name, value=[])

        target_list = self.parameters[list_name].value
        if not isinstance(target_list, list):
            raise TypeError("Parameter {} is not a list".format(list_name))
        return target_list


class DeltaJSON(object):

    def __init__(self):
        self.managed_objects = {}

    def __str__(self):
        return self.serialize()

    def serialize(self):
        """Get serialized delta JSON"""
        return json.dumps([mo.serialize() for mo in self.managed_objects.values()], indent=4, separators=(',', ':'))

    def append_managed_object(self, dist_name, operation="update"):
        """Add managed object to delta"""
        self.managed_objects[dist_name] = DeltaManagedObject(dist_name, operation)

    def append_parameter_update(self, dist_name, parameter, value):
        """Add managed object parameter update to delta"""
        self._assert_managed_object_exist(dist_name)
        self.managed_objects[dist_name].append_parameter(parameter, value)

    def append_parameter_delete(self, dist_name, parameter):
        """Add managed object parameter delete to delta"""
        self._assert_managed_object_exist(dist_name)
        self.managed_objects[dist_name].append_parameter(parameter, value="", operation="delete")

    def append_list_items(self, dist_name, list_name, *args):
        """Add list items to delta."""
        self._assert_managed_object_exist(dist_name)
        self.managed_objects[dist_name].append_list_items(list_name, *args)

    def append_complex_item(self, dist_name, list_name, **kwargs):
        """Add coplex type item to delta."""
        self._assert_managed_object_exist(dist_name)
        self.managed_objects[dist_name].append_complex_item(list_name, **kwargs)

    def _assert_managed_object_exist(self, dist_name):
        if dist_name not in self.managed_objects:
            self.append_managed_object(dist_name)


class DeltaInterface(object):

    delta_store = AliasStore()

    @classmethod
    def create_delta(cls, delta_id="default"):
        """
        Create new delta recommissioning JSON.

        :param string delta_id: ID of delta JSON.
        """
        cls.delta_store.add(DeltaJSON(), delta_id)

    @classmethod
    def get_delta(cls, delta_id="default"):
        """
        Get serialized delta JSON.

        :param string delta_id: ID of delta JSON.
        """
        return cls.delta_store.get(delta_id).serialize()

    @classmethod
    def save_delta(cls, target_file_name="delta.json", delta_id="default"):
        """
        Save serialized delta JSON to file.

        :param string target_file_name: target filename.
        :param string delta_id: ID of delta JSON.
        """
        ensure_parent_dir_exists(target_file_name)
        with open(target_file_name, 'w') as delta_json:
            delta_json.write(cls.get_delta(delta_id))

    @classmethod
    def append_managed_object_to_delta(cls, dist_name, operation, delta_id="default"):
        """
        Append managed object to delta.

        :param string dist_name: Object dist name
        :param string operation: Parameter operation (create, update or delete)
        :param string delta_id: ID of delta JSON.
        """
        operation = operation.lower()
        if operation not in ("update", "delete", "create"):
            raise ValueError("Operation not allowed. Should be one of [update, delete, create]")

        cls.delta_store.get(delta_id).append_managed_object(dist_name, operation)

    @classmethod
    def append_parameter_update_to_delta(cls, dist_name, parameter, value, delta_id="default"):
        """
        Append parameter update to delta.

        :param string dist_name: Object distName
        :param string parameter: Name of parameter to update
        :param string/list value: value
        :param string delta_id: ID of delta JSON.
        """

        cls.delta_store.get(delta_id).append_parameter_update(dist_name, parameter, value)

    @classmethod
    def append_parameter_delete_to_delta(cls, dist_name, parameter, delta_id="default"):
        """
        Append parameter delete to delta.

        :param string dist_name: Object distName
        :param string parameter: Name of parameter to delete
        :param string delta_id: ID of delta JSON.
        """

        cls.delta_store.get(delta_id).append_parameter_delete(dist_name, parameter)

    @classmethod
    def append_list_items_to_delta(cls, dist_name, list_name, args, **kwargs):
        """
        Append simple type items to list

        :param string dist_name: Object distName.
        :param string list_name: List name (parameter of list type).
        :param list args: list with items to be added to delta
        :param string delta_id: ID of delta JSON (via kwargs).
        """
        delta_id = kwargs.get("delta_id", "default")

        cls.delta_store.get(delta_id).append_list_items(dist_name, list_name, *args)

    @classmethod
    def append_complex_item_to_delta(cls, dist_name, list_name, delta_id="default", **kwargs):
        """
        Append complex type item to list.

        :param string dist_name: Object distName
        :param string list_name: List name (parameter of list type).
        :param string delta_id: ID of delta JSON.
        """

        cls.delta_store.get(delta_id).append_complex_item(dist_name, list_name, **kwargs)

    @classmethod
    def remove_delta(cls, delta_id="default"):
        """
        Remove delta recommissioning JSON with given delta_id.

        :param string delta_id: ID of delta JSON.
        """
        cls.delta_store.remove(delta_id)

    @classmethod
    def remove_all_delta_id(cls):
        """
        Remove all delta recommissioning JSONs.
        """
        cls.delta_store.reset()
